INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('e6f5a18d-7fe1-21bc-e264-2b455c92a346','PSR Dilemma','Chapter 12 Section 2','Your annual leave dates are pencilled into your diary, but your superior has not authorized your absence. A colleague urges you to travel tonight.','["Seek authorization before leaving","Travel because diary dates are sufficient","Let a colleague sign attendance for you","Treat the booking receipt as approval"]'::jsonb,0,'Under PSR Rule 120202, Annual Leave is the absence of an Officer from duty for a period specified in Rule 120203 as may be authorized by a superior Officer. In this situation, the consistent action is: Seek authorization before leaving. The other actions do not satisfy that requirement.','Chapter 12 Section 2','PSR 120202','Under PSR Rule 120202, Annual Leave is the absence of an Officer from duty for a period specified in Rule 120203 as may be authorized by a superior Officer.','Chapter12_Section2.xlsx / Sheet1',5,'scenario',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('d18aee81-8058-79a9-ed03-503b68c73541','PSR Dilemma','Chapter 12 Section 2','Your unit needs cover throughout the year. You propose splitting your annual leave into four separate blocks.','["Request four blocks as the normal arrangement","Revise the plan to one period or at most two instalments","Carry all leave into next year","Take only public holidays as annual leave"]'::jsonb,1,'Under PSR Rule 120206, full leave will normally be taken at one time, but it may be taken in not more than two installments. In this situation, the consistent action is: Revise the plan to one period or at most two instalments. The other actions do not satisfy that requirement.','Chapter 12 Section 2','PSR 120206','Under PSR Rule 120206, full leave will normally be taken at one time, but it may be taken in not more than two installments.','Chapter12_Section2.xlsx / Sheet1',12,'scenario',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('adfec222-6ef9-e649-1319-8070ff295d7c','PSR Dilemma','Chapter 12 Section 2','You have approved annual leave and intend to spend it abroad. Your itinerary and overseas address are ready.','["Tell only your travelling companion","Wait until your return to mention the trip","Inform the Permanent Secretary/Head before departure and provide the address","Assume approval of leave replaces the notification"]'::jsonb,2,'Under PSR Rule 120207(a), an Officer who desires to spend annual leave abroad must inform the Permanent Secretary/Head of Extra-Ministerial Office before proceeding and provide details of his address. In this situation, the consistent action is: Inform the Permanent Secretary/Head before departure and provide the address. The other actions do not satisfy that requirement.','Chapter 12 Section 2','PSR 120207','Under PSR Rule 120207(a), an Officer who desires to spend annual leave abroad must inform the Permanent Secretary/Head of Extra-Ministerial Office before proceeding and provide details of his address.','Chapter12_Section2.xlsx / Sheet1',14,'scenario',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('e0bd5079-0b56-12cf-fb09-0a340a8e8f46','PSR Dilemma','Chapter 12 Section 2','While on vacation leave, you are formally required to perform official duty for several days. The leave ledger still counts those days as holiday.','["Keep counting the duty days as leave consumed","Delete the entire annual leave record","Treat the days as unpaid absence","Record the duty period as leave-earning, not leave-consuming"]'::jsonb,3,'Under PSR Rule 120207(b), where an Officer is required during vacation leave to undertake duty, the period of duty is leave-earning and not leave-consuming. In this situation, the consistent action is: Record the duty period as leave-earning, not leave-consuming. The other actions do not satisfy that requirement.','Chapter 12 Section 2','PSR 120207','Under PSR Rule 120207(b), where an Officer is required during vacation leave to undertake duty, the period of duty is leave-earning and not leave-consuming.','Chapter12_Section2.xlsx / Sheet1',15,'scenario',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('331e9680-182b-8e34-208b-532f7aacb6eb','PSR Dilemma','Chapter 12 Section 2','Your leave was curtailed for an official assignment. The assignment is now complete and a colleague suggests saving the balance for several years.','["Arrange the curtailed portion immediately, no later than 90 days after the assignment","Save it indefinitely","Transfer the days to a colleague","Wait until retirement"]'::jsonb,0,'Under PSR Rule 120210, any portion of leave curtailed must be taken immediately and not later than ninety days after completion of the assignment. In this situation, the consistent action is: Arrange the curtailed portion immediately, no later than 90 days after the assignment. The other actions do not satisfy that requirement.','Chapter 12 Section 2','PSR 120210','Under PSR Rule 120210, any portion of leave curtailed must be taken immediately and not later than ninety days after completion of the assignment.','Chapter12_Section2.xlsx / Sheet1',19,'scenario',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('126066e3-3b7a-6ffe-6fa2-bcaedac7ff44','PSR Dilemma','Chapter 13 Section 3','You wake up too ill to attend work. Your supervisor is expecting you, but no notification has been sent.','["Stay silent until you recover","Notify your ministry or agency in writing or by another means","Ask a friend to pretend you are in the office","Record the day as official travel"]'::jsonb,1,'Under PSR Chapter 13, Section 3, Rule 130301, an Officer who is ill and unable to report for duty must notify his Ministry or Agency in writing or by any other means of communication. In this situation, the consistent action is: Notify your ministry or agency in writing or by another means. The other actions do not satisfy that requirement.','Chapter 13 Section 3','PSR 130301','Under PSR Chapter 13, Section 3, Rule 130301, an Officer who is ill and unable to report for duty must notify his Ministry or Agency in writing or by any other means of communication.','Chapter13_Section3.xlsx / Sheet1',2,'scenario',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('1c389699-0b2a-db10-04ea-60445d0db694','PSR Dilemma','Chapter 13 Section 3','You obtain medical treatment while away from your usual duty location. You have not yet told your employer.','["Wait for the next annual appraisal","Report only if asked","Report the treatment to your employer within 48 hours","Keep it private even if it explains absence"]'::jsonb,2,'Under PSR Rule 130302, an Officer receiving medical treatment within or outside the location of his duty post must report to his employer within 48 hours. In this situation, the consistent action is: Report the treatment to your employer within 48 hours. The other actions do not satisfy that requirement.','Chapter 13 Section 3','PSR 130302','Under PSR Rule 130302, an Officer receiving medical treatment within or outside the location of his duty post must report to his employer within 48 hours.','Chapter13_Section3.xlsx / Sheet1',6,'scenario',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('ace0cdf8-5fac-c6e7-5c0f-20bfb754d38b','PSR Dilemma','Chapter 13 Section 3','An officer is so ill that they cannot visit the health provider. You are the next of kin assisting them.','["Wait until the officer can walk unaided","Ask a colleague to diagnose the illness","Issue your own excuse-duty certificate","Notify the health provider about the officer’s condition"]'::jsonb,3,'Under PSR Rule 130304, where an Officer is so ill that he is physically unable to present himself for medical examination, his Next of Kin shall notify the Healthcare Provider. In this situation, the consistent action is: Notify the health provider about the officer’s condition. The other actions do not satisfy that requirement.','Chapter 13 Section 3','PSR 130304','Under PSR Rule 130304, where an Officer is so ill that he is physically unable to present himself for medical examination, his Next of Kin shall notify the Healthcare Provider.','Chapter13_Section3.xlsx / Sheet1',11,'scenario',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('2bb8ea54-b2d5-32f3-95f7-54071a62314d','PSR Dilemma','Chapter 13 Section 3','An officer remains unfit for duty after three months of certified illness. The file reaches your desk for the next step.','["Arrange referral to a Medical Board","Extend certificates indefinitely without review","Treat the officer as automatically retired","Delete the earlier certificates"]'::jsonb,0,'Under PSR Rule 130305, if the Officer is still not fit for duty after three months sick leave, he shall be examined by a Medical Board. In this situation, the consistent action is: Arrange referral to a Medical Board. The other actions do not satisfy that requirement.','Chapter 13 Section 3','PSR 130305','Under PSR Rule 130305, if the Officer is still not fit for duty after three months sick leave, he shall be examined by a Medical Board.','Chapter13_Section3.xlsx / Sheet1',19,'scenario',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('a0988ab8-e66a-9608-7119-77c518549fd7','PSR Dilemma','Chapter 13 Section 3','A Medical Board has issued recommendations that differ from the earlier advice of the health provider. You must process the case.','["Use whichever advice is more convenient","Follow the Medical Board recommendations, which supersede the provider’s advice","Ignore both until next year","Let a colleague choose without consulting the file"]'::jsonb,1,'Under PSR Rule 130307, the Officer must comply with the Medical Board’s recommendations, which supersede any medical advice already given by a Healthcare Provider. In this situation, the consistent action is: Follow the Medical Board recommendations, which supersede the provider’s advice. The other actions do not satisfy that requirement.','Chapter 13 Section 3','PSR 130307','Under PSR Rule 130307, the Officer must comply with the Medical Board’s recommendations, which supersede any medical advice already given by a Healthcare Provider.','Chapter13_Section3.xlsx / Sheet1',25,'scenario',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('f0d88022-07dc-7c80-fa09-614013b1b86c','PSR Dilemma','Chapter 2 Section 2','A professional recruit needs additional qualifying experience before appointment in the full grade. You are preparing the appointment paperwork.','["Appoint permanently in the full grade with no training","Mark the recruit as retired","Use the applicable trainee or pupil appointment","Waive all professional requirements"]'::jsonb,2,'Under PSR Rule 020204(a), a candidate may be appointed as trainee or pupil where he requires additional professional experience before he can be regarded as fully qualified for appointment to a specific post. In this situation, the consistent action is: Use the applicable trainee or pupil appointment. The other actions do not satisfy that requirement.','Chapter 2 Section 2','PSR 020204','Under PSR Rule 020204(a), a candidate may be appointed as trainee or pupil where he requires additional professional experience before he can be regarded as fully qualified for appointment to a specific post.','Chapter2_Section2.xlsx / Sheet1',13,'scenario',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('a98075b0-3038-a9c2-3394-ea2411fcb6ce','PSR Dilemma','Chapter 2 Section 2','A trainee has satisfactorily completed the prescribed training. Your unit must prepare the next appointment action.','["Keep trainee status indefinitely","Dismiss the trainee automatically","Skip all confirmation requirements","Move to the full grade on probation"]'::jsonb,3,'Under PSR Rule 020204(a), on completion of the trainee period, the pupil may be appointed to the full grade on probation. In this situation, the consistent action is: Move to the full grade on probation. The other actions do not satisfy that requirement.','Chapter 2 Section 2','PSR 020204','Under PSR Rule 020204(a), on completion of the trainee period, the pupil may be appointed to the full grade on probation.','Chapter2_Section2.xlsx / Sheet1',16,'scenario',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('99cc6dc5-db5c-0abc-c9aa-6e674bced96e','PSR Dilemma','Chapter 2 Section 2','An already confirmed officer is appointed to a training grade. HR asks how to treat the officer during training.','["Treat the arrangement as secondment","Cancel the existing confirmation automatically","Classify the officer as a new unconfirmed recruit","Record permanent abandonment of the old post"]'::jsonb,0,'Under PSR Rule 020204(b), a confirmed Officer advanced to a training grade for necessary experience to qualify for substantive promotion to a senior post is treated as if he had been seconded thereto. In this situation, the consistent action is: Treat the arrangement as secondment. The other actions do not satisfy that requirement.','Chapter 2 Section 2','PSR 020204','Under PSR Rule 020204(b), a confirmed Officer advanced to a training grade for necessary experience to qualify for substantive promotion to a senior post is treated as if he had been seconded thereto.','Chapter2_Section2.xlsx / Sheet1',18,'scenario',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('169a53c0-4798-5144-76a2-ffb1f850ec49','PSR Dilemma','Chapter 2 Section 2','A proposed training secondment would extend beyond the normal training period. You are asked to process it as routine.','["Approve any length without referral","Seek special advice from OHCSF for the longer period","Remove the training end date","Convert it into annual leave"]'::jsonb,1,'Under PSR Rule 020204(b), extension beyond the normal training period may occur only with the special advice of the Office of the Head of the Civil Service of the Federation. In this situation, the consistent action is: Seek special advice from OHCSF for the longer period. The other actions do not satisfy that requirement.','Chapter 2 Section 2','PSR 020204','Under PSR Rule 020204(b), extension beyond the normal training period may occur only with the special advice of the Office of the Head of the Civil Service of the Federation.','Chapter2_Section2.xlsx / Sheet1',20,'scenario',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('b1a64c72-420c-10bf-3126-3df032ea93cd','PSR Dilemma','Chapter 2 Section 2','A confirmed officer in a lower post has been converted to a higher post. A draft letter places the officer on probation again solely because of that conversion.','["Sign the draft unchanged","Erase the earlier confirmation record","Revise the letter: the confirmed officer is not put on probation again on this basis","Treat the officer as a temporary visitor"]'::jsonb,2,'Under PSR Rule 020205, an Officer confirmed in a lower pensionable post is not regarded as on probation in a higher post to which he is converted. In this situation, the consistent action is: Revise the letter: the confirmed officer is not put on probation again on this basis. The other actions do not satisfy that requirement.','Chapter 2 Section 2','PSR 020205','Under PSR Rule 020205, an Officer confirmed in a lower pensionable post is not regarded as on probation in a higher post to which he is converted.','Chapter2_Section2.xlsx / Sheet1',23,'scenario',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('a0dfdfd5-2264-8fca-b04f-cece5d5dd137','PSR Dilemma','Chapter 3 Section 5','You are a newly appointed professional officer covered by the compulsory confirmation examination requirement. There is no Government exemption, and you are planning your development timetable.','["Leave the examination until retirement","Wait five years before considering it","Assume your degree automatically exempts you","Plan to pass within two years of appointment"]'::jsonb,3,'Under PSR Rule 030501, the listed Officers are required to pass the examinations within two years of taking up their appointments in the Federal Public Service. In this situation, the consistent action is: Plan to pass within two years of appointment. The other actions do not satisfy that requirement.','Chapter 3 Section 5','PSR 030501','Under PSR Rule 030501, the listed Officers are required to pass the examinations within two years of taking up their appointments in the Federal Public Service.','Chapter3_Section5.xlsx / Sheet1',3,'scenario',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('f420fe70-c704-31be-1d66-14f9bce8a327','PSR Dilemma','Chapter 3 Section 5','A direct appointee covered by the confirmation examination rule has served only three months and asks HR to register them immediately.','["Plan eligibility after six months of service","Declare immediate eligibility after one week","Require ten years of service","Tell the officer direct appointees can never sit"]'::jsonb,0,'Under PSR Rule 030501(a), Officers eligible for the examinations must have served for six months after taking up their appointments. In this situation, the consistent action is: Plan eligibility after six months of service. The other actions do not satisfy that requirement.','Chapter 3 Section 5','PSR 030501','Under PSR Rule 030501(a), Officers eligible for the examinations must have served for six months after taking up their appointments.','Chapter3_Section5.xlsx / Sheet1',6,'scenario',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('cdaf81ea-17ef-f5d4-d944-9cbe105dc7c9','PSR Dilemma','Chapter 3 Section 5','An officer is promoted from an unconfirmed junior post into a covered professional grade. The officer believes promotion alone removes the confirmation examination requirement.','["Agree that promotion automatically removes it","Include the officer in the applicable examination requirement","Treat the officer as retired","Replace the examination with a private club membership"]'::jsonb,1,'Under PSR Rule 030501(b), Senior Executive Officers, Administrative Officers and Professionals promoted from unconfirmed junior posts are required to pass the examination. In this situation, the consistent action is: Include the officer in the applicable examination requirement. The other actions do not satisfy that requirement.','Chapter 3 Section 5','PSR 030501','Under PSR Rule 030501(b), Senior Executive Officers, Administrative Officers and Professionals promoted from unconfirmed junior posts are required to pass the examination.','Chapter3_Section5.xlsx / Sheet1',8,'scenario',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('01ae6da9-cd5e-06a3-5379-bf40752e0a69','PSR Dilemma','Chapter 3 Section 5','An officer transfers from another Scheduled Service at age 35 and has not satisfied confirmation conditions. You review the examination requirement.','["Assume every transfer is exempt","Base the decision only on the new office location","Apply the requirement for transferred officers under 40 who have not satisfied confirmation conditions","Wait until the officer turns 60"]'::jsonb,2,'Under PSR Rule 030501(c), transferred Officers from other Scheduled Service are required to pass where, at the date of transfer, they are under forty years and have not satisfied conditions for confirmation. In this situation, the consistent action is: Apply the requirement for transferred officers under 40 who have not satisfied confirmation conditions. The other actions do not satisfy that requirement.','Chapter 3 Section 5','PSR 030501','Under PSR Rule 030501(c), transferred Officers from other Scheduled Service are required to pass where, at the date of transfer, they are under forty years and have not satisfied conditions for confirmation.','Chapter3_Section5.xlsx / Sheet1',10,'scenario',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions(id,category,chapter,question_text,options,correct_option_index,explanation,section_key,rule_ref,rule_excerpt,source_file,source_row,question_kind,challenge_tier) VALUES('543c0e70-4d83-c411-615f-d9ba49338e63','PSR Dilemma','Chapter 3 Section 5','An officer is preparing for further advancement beyond GL. 10. A colleague suggests an attendance slip from any unapproved social seminar will suffice.','["Accept the social seminar slip","Ignore prescribed examinations","Use a residential association meeting as the qualification","Attend ASCON, PSIN, CMD or another approved institution and pass the prescribed examination"]'::jsonb,3,'Under PSR Rule 030501(d), for further advancement beyond GL. 10, Officers shall attend ASCON, PSIN, CMD or any other approved institution and pass the prescribed examination. In this situation, the consistent action is: Attend ASCON, PSIN, CMD or another approved institution and pass the prescribed examination. The other actions do not satisfy that requirement.','Chapter 3 Section 5','PSR 030501','Under PSR Rule 030501(d), for further advancement beyond GL. 10, Officers shall attend ASCON, PSIN, CMD or any other approved institution and pass the prescribed examination.','Chapter3_Section5.xlsx / Sheet1',13,'scenario',3) ON CONFLICT(id) DO NOTHING;
COMMIT;